-- Distinct influence facets and explicit epistemic targets, without implied effects.
BEGIN;
ALTER TABLE niccolo.actor_epistemic_state_events ADD COLUMN influence_target TEXT;
ALTER TABLE niccolo.actor_epistemic_state_events DROP CONSTRAINT actor_epistemic_state_events_dimension_check;
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_state_events_dimension_check CHECK (dimension IN (
 'EXPOSURE','ACCESS','PERCEPTION','ATTENTION','EXAMINATION','COMPREHENSION','RECALL','SUSPICION','INCLINATION','DOUBT','BELIEF','SUSPENDED_JUDGMENT','CLAIMED_KNOWLEDGE','PERCEIVED_KNOWLEDGE','EVIDENCE_SUPPORTED_KNOWLEDGE',
 'INTEREST','CURIOSITY','INDIFFERENCE','AVERSION','LIMITED_INQUIRY','DENIABILITY_PRESERVATION','DELEGATED_KNOWING','DOCUMENTATION_AVOIDANCE',
 'TRUST_COMPETENCE','TRUST_CONFIDENTIALITY','TRUST_TRUTHFULNESS','LOYALTY','EGO_PROTECTION','IDENTITY_PROTECTION',
 'AUTONOMY_DECIDE','AUTONOMY_REFUSE','AUTONOMY_DISAGREE','AUTONOMY_EXIT','AUTONOMY_SEEK_REVIEW','AUTONOMY_ACQUIRE_INFORMATION','AUTONOMY_REVISE_COMMITMENTS',
 'INCENTIVE','PRESSURE','COMMUNICATED_THREAT','ADVERSE_CONDITION','COERCION','CONSTRAINT','DEPENDENCY','LEVERAGE',
 'THREAT_CAPABILITY','THREAT_INTENT','THREAT_PERCEIVED_CREDIBILITY','THREAT_OUTCOME','VULNERABILITY','COERCION_SUSCEPTIBILITY','COMPLIANCE','CONSENT','SUBMISSION',
 'INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS'));
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_influence_qualification CHECK (
 (dimension IN ('INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS'))=(influence_target IS NOT NULL)
 AND (influence_target IS NULL OR (target_object_id IS NOT NULL AND influence_target IN ('BELIEF','ATTENTION','INTEREST','CURIOSITY','TRUST','ACCEPTANCE','INTERPRETATION','INVESTIGATION_PRIORITY','WILLINGNESS_TO_EXAMINE'))));
ALTER TABLE niccolo.actor_epistemic_state_events DROP CONSTRAINT actor_epistemic_counterparty_qualification;
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_counterparty_qualification CHECK (
 (counterparty_actor_id IS NULL OR (counterparty_actor_id<>subject_actor_id AND dimension IN ('INCENTIVE','PRESSURE','COMMUNICATED_THREAT','ADVERSE_CONDITION','COERCION','CONSTRAINT','DEPENDENCY','LEVERAGE','THREAT_CAPABILITY','THREAT_INTENT','THREAT_PERCEIVED_CREDIBILITY','THREAT_OUTCOME','VULNERABILITY','COERCION_SUSCEPTIBILITY','COMPLIANCE','CONSENT','SUBMISSION','INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS')))
 AND (dimension NOT IN ('THREAT_CAPABILITY','THREAT_INTENT','INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT') OR counterparty_actor_id IS NOT NULL));
CREATE FUNCTION niccolo.validate_actor_influence_revision() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,niccolo AS $$ BEGIN
 IF NEW.revises_event_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM niccolo.actor_epistemic_state_events p WHERE p.workspace_id=NEW.workspace_id AND p.situation_id=NEW.situation_id AND p.event_id=NEW.revises_event_id AND p.influence_target IS NOT DISTINCT FROM NEW.influence_target)
 THEN RAISE EXCEPTION 'Revision must preserve the qualified influence target' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER actor_influence_revision BEFORE INSERT ON niccolo.actor_epistemic_state_events FOR EACH ROW EXECUTE FUNCTION niccolo.validate_actor_influence_revision();
COMMIT;
